    logic [31:0] pc_plus4;
    logic [31:0] branch_target;
    logic [31:0] jal_target;
    logic [31:0] jalr_target;
    logic [31:0] ctrl_target;
    logic        branch_taken;
    logic        is_control;
    logic        actual_taken;
    logic [31:0] actual_next_pc;
    logic [31:0] wb_data;
    logic        issue_fire;

    assign issue_fire = issue_valid & issue_ready;

    assign op_a = issue_fire ? issue_operand1 : 32'd0;
    assign op_b = issue_fire ? (issue_use_imm ? issue_imm : issue_operand2) : 32'd0;

    always_comb begin
        alu_result = 32'd0;
        if (issue_fire) begin
            case (issue_alu_op)
                ALU_ADD:   alu_result = op_a + op_b;
                ALU_SUB:   alu_result = op_a - op_b;
                ALU_SLL:   alu_result = op_a << op_b[4:0];
                ALU_SLT:   alu_result = ($signed(op_a) < $signed(op_b)) ? 32'd1 : 32'd0;
                ALU_SLTU:  alu_result = (op_a < op_b) ? 32'd1 : 32'd0;
                ALU_XOR:   alu_result = op_a ^ op_b;
                ALU_SRL:   alu_result = op_a >> op_b[4:0];
                ALU_SRA:   alu_result = $signed(op_a) >>> op_b[4:0];
                ALU_OR:    alu_result = op_a | op_b;
                ALU_AND:   alu_result = op_a & op_b;
                default:   alu_result = op_a + op_b;
            endcase
        end
    end

    always_comb begin
        branch_taken = 1'b0;
        if (issue_fire) begin
            case (issue_alu_op)
                ALU_BEQ:  branch_taken = (op_a == op_b);
                ALU_BNE:  branch_taken = (op_a != op_b);
                ALU_BLT:  branch_taken = ($signed(op_a) < $signed(op_b));
                ALU_BGE:  branch_taken = ($signed(op_a) >= $signed(op_b));
                ALU_BLTU: branch_taken = (op_a < op_b);
                ALU_BGEU: branch_taken = (op_a >= op_b);
                default:  branch_taken = 1'b0;
            endcase
        end
    end

    assign pc_plus4      = issue_fire ? (issue_pc + 32'd4) : 32'd0;
    assign branch_target = issue_fire ? (issue_pc + issue_imm) : 32'd0;
    assign jal_target    = issue_fire ? (issue_pc + issue_imm) : 32'd0;
    assign jalr_target   = issue_fire ? ((op_a + issue_imm) & 32'hFFFF_FFFE) : 32'd0;

    always_comb begin
        ctrl_target = pc_plus4;
        if (issue_is_branch) begin
            ctrl_target = branch_target;
        end else if (issue_is_jal) begin
            ctrl_target = jal_target;
        end else if (issue_is_jalr) begin
            ctrl_target = jalr_target;
        end
    end

    assign is_control = issue_is_branch | issue_is_jal | issue_is_jalr;

    always_comb begin
        actual_taken = 1'b0;
        if (issue_fire) begin
            if (issue_is_branch) begin
                actual_taken = branch_taken;
            end else if (issue_is_jal || issue_is_jalr) begin
                actual_taken = 1'b1;
            end
        end
    end

    assign actual_next_pc = actual_taken ? ctrl_target : pc_plus4;

    always_comb begin
        wb_data = 32'd0;
        if (issue_fire) begin
            wb_data = alu_result;
            case (issue_wb_sel)
                WB_ALU:   wb_data = alu_result;
                WB_PC4:   wb_data = pc_plus4;
                WB_LOAD:  wb_data = alu_result;
                WB_IMM:   wb_data = issue_imm;
                WB_AUIPC: wb_data = issue_pc + issue_imm;
                default:  wb_data = alu_result;
            endcase
        end
    end

    assign issue_ready = rst_n & ~halted & ~flush;

    assign alu_complete_valid    = issue_fire;
    assign alu_complete_rob_index= issue_rob_index;
    assign alu_complete_prd      = issue_pdst;
    assign alu_complete_data     = wb_data;

    assign resolve_valid     = issue_fire & is_control;
    assign resolve_rob_index = issue_rob_index;
    assign resolve_pc        = issue_pc;
    assign resolve_actual    = actual_next_pc;

endmodule
"
    }
  ],
  "notes": "PPA repair without changing interfaces or architectural behavior. rename_unit: replaced the 8x8 physical-slot rank/winner comparators with a rotated-order scan (oldest-first), prefix-sum ranks, and one-hot restore scatter; converted speculative map, checkpoint slots, free-list entries and ready table to per-row/per-bit clock enables with operand-isolated map/free-list reads, removing whole-vector updates each cycle. physical_register_file: reduced to the 48 physical registers actually reachable by the free list (PR 0..47) and omitted hardwired PR 0. load_store_unit: stored only the 12-bit immediate, 2-bit size and 1-bit unsigned load flag instead of two full 32-bit instructions, and gated operand wake comparisons with entry valid. execute_alu: isolated branch comparisons through the already-gated op_a/op_b operands and removed unused ALU result cases. Self-checked reset values (spec map, free list, ready table, slots, pointers), alloc/flush mutual exclusion, ready/valid and stall/flush behavior, ECALL acceptance and halt freeze, and one-cycle completion/ready timing; no functional timing was intentionally changed."
}

