                                    2'd1: line_data[r][63:32]  <= mem_resp_data;
                                    2'd2: line_data[r][95:64]  <= mem_resp_data;
                                    default: line_data[r][127:96] <= mem_resp_data;
                                endcase
                                if (refill_word == 2'b11) begin
                                    line_tag[r]   <= req_addr[31:5];
                                    line_valid[r] <= 1'b1;
                                end
                            end
                        end
                        if (refill_word == 2'b11) begin
                            if (req_addr[3:2] == 2'b11) begin
                                resp_data_r <= mem_resp_data;
                            end
                            state <= ST_RESP;
                        end else begin
                            if (refill_word == req_addr[3:2]) begin
                                resp_data_r <= mem_resp_data;
                            end
                            refill_word <= refill_word + 2'b01;
                        end
                    end
                end
                ST_RESP: begin
                    state <= ST_IDLE;
                end
                default: state <= ST_IDLE;
            endcase
