        if (!rst_n) begin
            state       <= ST_IDLE;
            line_valid  <= 2'b0;
            req_addr    <= 32'b0;
            req_wdata   <= 32'b0;
            req_be      <= 4'b0;
            refill_word <= 2'b0;
            resp_rdata  <= 32'b0;
            resp_epoch  <= 2'b0;
        end else begin
            case (state)
                ST_IDLE: begin
                    if (cpu_req_valid && cpu_req_ready) begin
                        req_addr   <= cpu_req_addr;
                        req_wdata  <= cpu_req_wdata;
                        req_be     <= cpu_req_be;
                        resp_epoch <= cpu_req_epoch;
                        if (cpu_req_we) begin
                            if (hit) begin
                                for (r = 0; r < 2; r = r + 1) begin
                                    if (idx == r[0]) begin
                                        case (wsel)
                                            2'd0: line_data[r][31:0]    <= merged_word;
                                            2'd1: line_data[r][63:32]   <= merged_word;
                                            2'd2: line_data[r][95:64]   <= merged_word;
                                            default: line_data[r][127:96] <= merged_word;
                                        endcase
                                    end
                                end
                            end
                            state <= ST_WT;
                        end else if (hit) begin
                            resp_rdata <= hit_word;
                            state      <= ST_RESP;
                        end else begin
                            refill_word <= 2'b0;
                            state       <= ST_REFILL;
                        end
                    end
                end
                ST_REFILL: begin
                    if (mem_req_ready) begin
                        for (r = 0; r < 2; r = r + 1) begin
                            if (req_addr[4] == r[0]) begin
                                case (refill_word)
                                    2'd0: line_data[r][31:0]   <= mem_resp_data;
                                    2'd1: line_data[r][63:32]  <= mem_resp_data;
                                    2'd2: line_data[r][95:64]  <= mem_resp_data;
                                    default: line_data[r][127:96] <= mem_resp_data;
