                        if (refill_word == 2'b11) begin
                            if (req_addr[3:2] == 2'b11) begin
                                resp_rdata <= mem_resp_data;
                            end
                            state <= ST_RESP;
                        end else begin
                            if (refill_word == req_addr[3:2]) begin
                                resp_rdata <= mem_resp_data;
                            end
                            refill_word <= refill_word + 2'b01;
                        end
                    end
                end
                ST_WT: begin
                    if (mem_req_ready) begin
                        resp_rdata <= 32'b0;
                        state      <= ST_RESP;
                    end
                end
                ST_RESP: begin
                    state <= ST_IDLE;
                end
                default: state <= ST_IDLE;
            endcase
        end
    end

endmodule
