                for (sq_i = 0; sq_i < ROB_DEPTH; sq_i = sq_i + 1) begin
                    if (resolve_rob_index[1:0] == sq_i[1:0]) begin
                        if (ent_valid[sq_i] &&
                            (ent_index[sq_i] == resolve_rob_index) &&
                            ent_is_ctrl[sq_i]) begin
                            if (resolve_mispredict && !pending_flush) begin
                                pending_flush     <= 1'b1;
